const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const mountFuji = ee.Geometry.Point([138.727778, 35.360556]);
    const roi = mountFuji.buffer(5000); // 5km buffer around the summit

    const startDate2019 = '2019-12-01';
    const endDate2019 = '2019-12-31';
    const startDate2020 = '2020-12-01';
    const endDate2020 = '2020-12-31';

    // 2. Data Acquisition & Processing Function
    const getMonthlyComposite = function(startDate, endDate, geometry) {
        // Cloud masking function for Sentinel-2 SR
        function maskS2clouds(image) {
            const qa = image.select('QA60');
            // Bits 10 and 11 are clouds and cirrus, respectively.
            const cloudBitMask = 1 << 10;
            const cirrusBitMask = 1 << 11;
            // Both flags should be set to zero, indicating clear conditions.
            let mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
            // Also use the SCL band for more robust masking
            const scl = image.select('SCL');
            const clearMask = scl.eq(4).or(scl.eq(5)).or(scl.eq(6)).or(scl.eq(11));
            mask = mask.and(clearMask);
            return image.updateMask(mask).divide(10000); // Scale data
        }

        const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
            .filterDate(startDate, endDate)
            .filterBounds(geometry)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

        const size = collection.size().getInfo();
        if (size === 0) {
            return {
                image: null,
                count: size
            };
        }

        const maskedCollection = collection.map(maskS2clouds);
        const composite = maskedCollection.median();
        const ndsi = composite.normalizedDifference(['B3', 'B11']).rename('NDSI');

        return {
            image: ndsi,
            count: size
        };
    };

    // 3. Process data for both years
    const data2019 = getMonthlyComposite(startDate2019, endDate2019, roi);
    const data2020 = getMonthlyComposite(startDate2020, endDate2020, roi);

    console.log(`Images found for Dec 2019: ${data2019.count}`);
    console.log(`Images found for Dec 2020: ${data2020.count}`);

    if (data2019.count === 0 || data2020.count === 0) {
        console.log("Evidence: One or both periods had no images available.");
        console.log("A: Yes"); // Placeholder, final tag is below
        console.log("B: No"); // Placeholder, final tag is below
        console.log("C1: Empty Collection (No images found in date/location for one or both comparison points).");
        console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).");
        console.log("C3: Calculation Failure (Result is `None`, `NaN`, or invalid).");
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
        console.log("Was the mean NDSI for Mount Fuji lower in December 2020 than December 2019?");
        console.log("C1");
        return;
    }

    // 4. Calculation
    const scale = 1000;
    const commonReducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats2019 = data2019.image.reduceRegion({
        reducer: commonReducer,
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const stats2020 = data2020.image.reduceRegion({
        reducer: commonReducer,
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const mean2019 = stats2019['NDSI_mean'];
    const pixels2019 = stats2019['NDSI_count'];
    const mean2020 = stats2020['NDSI_mean'];
    const pixels2020 = stats2020['NDSI_count'];

    console.log(`2019 Valid Pixels: ${pixels2019}, Mean NDSI: ${mean2019 !== null ? mean2019.toFixed(4) : 'N/A'}`);
    console.log(`2020 Valid Pixels: ${pixels2020}, Mean NDSI: ${mean2020 !== null ? mean2020.toFixed(4) : 'N/A'}`);

    // 5. Validation & Final Answer
    if (pixels2019 === 0 || pixels2020 === 0) {
        console.log("Evidence: At least one period had no valid (cloud-free) pixels over the area.");
        console.log("A: Yes"); // Placeholder, final tag is below
        console.log("B: No"); // Placeholder, final tag is below
        console.log("C1: Empty Collection (No images found in date/location for one or both comparison points).");
        console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).");
        console.log("C3: Calculation Failure (Result is `None`, `NaN`, or invalid).");
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
        console.log("Was the mean NDSI for Mount Fuji lower in December 2020 than December 2019?");
        console.log("C2");
        return;
    }

    if (mean2019 === null || mean2020 === null) {
        console.log("Evidence: Calculation returned a null value for mean NDSI.");
        console.log("A: Yes"); // Placeholder, final tag is below
        console.log("B: No"); // Placeholder, final tag is below
        console.log("C1: Empty Collection (No images found in date/location for one or both comparison points).");
        console.log("C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).");
        console.log("C3: Calculation Failure (Result is `None`, `NaN`, or invalid).");
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
        console.log("Was the mean NDSI for Mount Fuji lower in December 2020 than December 2019?");
        console.log("C3");
        return;
    }

    console.log("Evidence: The mean NDSI in Dec 2020 was compared to the mean NDSI in Dec 2019.");
    if (mean2020 < mean2019) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
